// Mock data for the classroom booking system

export const formatFloor = (floor) => {
  const f = Number(floor);
  if (f === 0) return 'Ground Floor';
  if (f === 1) return '1st Floor';
  if (f === 2) return '2nd Floor';
  return `Floor ${floor}`;
};

