export const getAllSections = () => {
  const result = [];
  academicStructure.years.forEach((yr) => {
    academicStructure.branches.forEach((br) => {
      br.sections.forEach((sec) => {
        result.push({
          id: `${yr.id}-${br.id}-${sec.id}`,
          yearId: yr.id,
          yearName: yr.name,
          branchId: br.id,
          branchName: br.id,
          fullBranchName: br.name,
          sectionId: sec.id,
          sectionName: sec.name,
          strength: sec.strength,
          label: `${yr.name} ${br.id} (${sec.name})`,
          shortLabel: `${yr.id}st-${br.id}-${sec.id}`,
        });
      });
    });
  });
  return result;
};

export const calculateSelectedStrength = (sectionIds) => {
  if (!Array.isArray(sectionIds) || sectionIds.length === 0) return 0;
  const allSecs = getAllSections();
  return sectionIds.reduce((sum, id) => {
    const sec = allSecs.find((s) => s.id === id);
    return sum + (sec ? sec.strength : 75);
  }, 0);
};

export const formatAudienceDescription = (sectionIds) => {
  if (!Array.isArray(sectionIds) || sectionIds.length === 0) return 'General Audience';
  const allSecs = getAllSections();
  const names = sectionIds.map((id) => {
    const match = allSecs.find((s) => s.id === id);
    return match ? `${match.yearName} ${match.branchId}${match.sectionName ? `-${match.sectionName}` : ''}` : id;
  });
  return names.join(', ');
};

